<?php require __DIR__.'/_guard.php'; $msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){$pid=(int)($_POST['product_id']??0);$qty=(int)($_POST['quantity']??0);$act=$_POST['action']??'';
 if($pid<1||$qty<1||!in_array($act,['in','out'],true))$err='Choose a product, action and positive quantity.';
 else {try{$conn->begin_transaction();$s=$conn->prepare('SELECT quantity FROM products WHERE id=? FOR UPDATE');$s->bind_param('i',$pid);$s->execute();$pr=$s->get_result()->fetch_assoc();$s->close();if(!$pr)throw new Exception('Product not found.');$before=(int)$pr['quantity'];if($act==='out'&&$qty>$before)throw new Exception('Stock out quantity cannot exceed available stock.');$after=$act==='in'?$before+$qty:$before-$qty;$u=$conn->prepare('UPDATE products SET quantity=? WHERE id=?');$u->bind_param('ii',$after,$pid);$u->execute();$u->close();$h=$conn->prepare('INSERT INTO stock_history(product_id,user_id,action,quantity,previous_quantity,new_quantity) VALUES(?,?,?,?,?,?)');$uid=(int)$_SESSION['user_id'];$h->bind_param('iisiii',$pid,$uid,$act,$qty,$before,$after);$h->execute();$h->close();$conn->commit();$msg='Stock updated and history saved successfully.';}catch(Throwable $e){$conn->rollback();$err=$e->getMessage();}}}
$products=$conn->query('SELECT id,product_name,product_code,quantity,reorder_level FROM products ORDER BY product_name');
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Stock In / Out</title><link rel="stylesheet" href="../assets/css/modern.css"></head><body><main class="page"><header class="topbar"><div><a class="brand" href="dashboard.php">Fresh<span>Mart</span></a><h1>Stock In / Out</h1><p class="muted">Record stock received into the store or issued from inventory.</p></div><a class="btn" href="dashboard.php">Dashboard</a></header><nav class="nav"><a href="dashboard.php">Overview</a><a href="stock.php">Stock In / Out</a><a href="history.php">Stock history</a><a href="low_stock.php">Low stock</a></nav><section class="panel"><h2>Update inventory</h2><?php if($msg):?><div class="alert success"><?=htmlspecialchars($msg)?></div><?php endif;?><?php if($err):?><div class="alert error"><?=htmlspecialchars($err)?></div><?php endif;?><form method="post" class="form-grid"><div><label>Product</label><select name="product_id" required><option value="">Select product</option><?php if($products)while($p=$products->fetch_assoc()):?><option value="<?=$p['id']?>"><?=htmlspecialchars($p['product_name'].' ('.$p['product_code'].') — available: '.$p['quantity'])?></option><?php endwhile;?></select></div><div><label>Action</label><select name="action" required><option value="in">Stock In (receive)</option><option value="out">Stock Out (issue)</option></select></div><div><label>Quantity</label><input type="number" name="quantity" min="1" required></div><div style="align-self:end"><button class="btn primary" type="submit">Save stock change</button></div></form></section><section class="panel" style="margin-top:18px"><h2>Current inventory</h2><div class="table-wrap"><table><thead><tr><th>Code</th><th>Product</th><th>Available</th><th>Reorder level</th><th>Status</th></tr></thead><tbody><?php $list=$conn->query('SELECT product_code,product_name,quantity,reorder_level FROM products ORDER BY product_name');if($list)while($p=$list->fetch_assoc()):?><tr><td><?=htmlspecialchars($p['product_code'])?></td><td><?=htmlspecialchars($p['product_name'])?></td><td><?=$p['quantity']?></td><td><?=$p['reorder_level']?></td><td><?=$p['quantity']<=$p['reorder_level']?'<span class="badge warn">Low stock</span>':'<span class="badge">In stock</span>'?></td></tr><?php endwhile;?></tbody></table></div></section></main></body></html>
